"""Recovery contracts and an explicitly simulated developer point of view."""
import json
from build_final_project_workshop import icon


def build_recovery(root,twin,p,table):
    data=json.loads((root/'final-project/recovery.json').read_text())
    def duration(seconds):
        return '0' if not seconds else str(seconds//3600)+' h' if seconds%3600==0 else str(seconds//60)+' min' if seconds%60==0 else str(seconds)+' s'
    rows=[]
    details=''
    for row in data['cases']:
        rows.append([(row['id']+' · '+row['name'][0],row['id']+' · '+row['name'][1]),('<bdi dir="ltr">'+duration(row['rpo_seconds'])+'</bdi>','<bdi dir="ltr">'+duration(row['rpo_seconds'])+'</bdi>'),('<bdi dir="ltr">'+duration(row['rto_seconds'])+'</bdi>','<bdi dir="ltr">'+duration(row['rto_seconds'])+'</bdi>'),tuple(row['scope'])])
        details+=f'<details class="recovery-case" id="{row["id"]}"><summary><bdi>{row["id"]}</bdi>'+twin(*row['name'])+icon('plus')+'</summary><div class="disclosure-body">'
        for key,fa,en in [('why','چرا این هدف را انتخاب کردیم؟','Why choose this target?'),('budget','بودجهٔ بازیابی','Recovery budget'),('requires','چه چیزی باید برقرار باشد؟','Required conditions'),('test','چطور آن را اثبات کنیم؟','How to demonstrate it')]:
            details+='<h4>'+twin(fa,en)+'</h4>'+p(*row[key])
        details+='</div></details>'
    return '<section id="recovery" class="workshop-section recovery-section"><h2 class="workshop-heading"><span class="secnum" aria-hidden="true">05</span>'+twin('اگر سیستم خراب شد، چه قولی می‌دهیم؟','What happens when the system fails?')+'</h2>'+p('RPO می‌گوید حداکثر چه مقدار از آخرین داده‌ها را می‌توانیم از دست بدهیم. RTO می‌گوید حداکثر چه مدت تا بازگشتِ سرویسِ درست فرصت داریم. این‌ها دو قرارداد جدا هستند و برای هر نوع خرابی جدا انتخاب می‌شوند.','RPO bounds acceptable recent data loss. RTO bounds time until correct service is restored. They are separate objectives selected for each failure scenario.')+'<div class="recovery-definitions"><div><h3 lang="en" dir="ltr">RPO · Recovery Point Objective</h3>'+p('مثال: RPO پنج دقیقه یعنی نقطهٔ بازیابیِ پیوسته حداکثر پنج دقیقه عقب باشد؛ backup روزانه به‌تنهایی کافی نیست.','A five-minute RPO requires a contiguous recoverable point no more than five minutes behind; a daily backup alone is insufficient.')+'</div><div><h3 lang="en" dir="ltr">RTO · Recovery Time Objective</h3>'+p('ساعت از آغاز اختلال شروع می‌شود، نه از وقتی تیم آن را اعلام کرد. پایان، موفق‌شدن canary سرتاسری با داده و مجوز درست است، نه صرفاً روشن‌شدن DB.','Start the clock at failure onset, not incident declaration. Finish when an end-to-end canary succeeds with correct data and permissions, not merely when the database boots.')+'</div></div><p class="recovery-status">'+twin('هدف‌های منتخبِ طراحی پایلوت — هنوز اندازه‌گیری یا پیاده‌سازی نشده‌اند. این جدول SLA میزبانی سایت نیست.','Selected pilot design objectives — not implemented or measured. This is not the study site host’s SLA.')+'</p>'+table([('سناریو','Scenario'),('سقف RPO','RPO limit'),('سقف RTO','RTO limit'),('مرزِ ادعا','Scope')],rows)+details+'<div class="recovery-measure"><h3>'+twin('ثبت نتیجهٔ drill، قبل از هر ادعای پایداری','Record the drill before claiming resilience')+'</h3>'+p('یک canary شماره‌دار را پیش از خرابی در journal مستقل ثبت می‌کنیم. آخرین نقطهٔ پیوستهٔ قابل‌بازیابی، دادهٔ ازدست‌رفته و زمان بازگشتِ canary را مقایسه می‌کنیم. snapshot و WAL باید با artifactها، guard حذف و policy فعلی سازگار باشند.','Record sequenced canaries in an independent journal before failure. Compare the last contiguous recovery point, missing data, and time to a successful recovered canary. Snapshots/WAL must agree with artifacts, deletion guards, and current policy.')+p('در restore، ACL قدیمی مجوزِ فعلی نیست. اگر IAM معتبر، حذف‌ها یا fencing قابل‌اثبات نباشند، دسترسی حساس بسته می‌ماند و RTO ناموفق ثبت می‌شود. «replica داریم» یا «archive_timeout را تنظیم کردیم» به‌تنهایی مدرکِ این هدف‌ها نیست.','An old restored ACL is not current authority. If IAM, deletions, or fencing cannot be validated, sensitive access stays closed and the RTO is a miss. Replicas or archive_timeout settings alone do not establish these objectives.')+'</div>'+p('برای خودِ وب‌سایتِ فعلی: RPO نسبت به آخرین commit تأییدشده در GitHub صفر است؛ تغییرهای محلیِ push‌نشده خارج این ادعا هستند. هدفِ redeploy دستی، ۳۰ دقیقه است و هنوز drill نشده؛ تضمین Vercel یا GitHub نیست.','For the current website: RPO is zero relative to the last verified GitHub commit, excluding unpushed local changes. The manual-redeploy objective is 30 minutes, not yet drilled and not a Vercel/GitHub guarantee.')+'<div class="workshop-links"><a class="workshop-link" href="#ADR-015">ADR-015'+icon('next')+'</a><a class="workshop-link" href="recovery.json">'+twin('قراردادها و فرض‌ها (JSON)','Contracts and assumptions (JSON)')+icon('next')+'</a><a class="workshop-link" href="../docs/RECOVERY.md">'+twin('راهنمای آزمون بازیابی','Recovery drill guide')+icon('next')+'</a></div><p class="recovery-sources"><a href="https://docs.aws.amazon.com/whitepapers/latest/disaster-recovery-workloads-on-aws/introduction.html" target="_blank" rel="noopener">AWS · RPO/RTO</a> · <a href="https://www.postgresql.org/docs/current/continuous-archiving.html" target="_blank" rel="noopener">PostgreSQL · PITR</a> · <a href="https://www.postgresql.org/docs/current/runtime-config-wal.html" target="_blank" rel="noopener">PostgreSQL · WAL</a></p></section>'


def build_outcome(twin,p,ul):
    scenes=[
        ('تعریف برنامه','Define the app','برنامه و ابزارهای مجازش را تعریف می‌کنم.','I define the app and its permitted tools.','Configured',
         '<dl class="pov-config"><div><dt>App</dt><dd>Incident Investigator</dd></div><div><dt>Tenant</dt><dd>demo-sandbox</dd></div><div><dt>Model</dt><dd>Provider adapter · proposed</dd></div><div><dt>Tools</dt><dd>read_metrics · read_traces · read_runbook</dd></div></dl>'),
        ('درخواست اجرا','Submit a run','یک alert می‌فرستم؛ همان کلیدِ درخواست باید همیشه همان run را برگرداند.','I submit an alert; the same request key must return the same run.','Accepted',
         '<dl class="pov-config"><div><dt>Run ID</dt><dd>run_demo_001</dd></div><div><dt>Idempotency</dt><dd>alert_demo_001</dd></div><div><dt>State</dt><dd>Committed before acknowledgement</dd></div></dl>'),
        ('جمع‌آوری شاهد','Gather evidence','فقط منابعِ مجازِ همین tenant خوانده می‌شوند. این سه مقدار، دادهٔ مصنوعیِ سناریو هستند.','Only this tenant’s permitted sources are read. These three values are synthetic scenario data.','Running',
         '<dl class="pov-config"><div><dt>Metrics</dt><dd>Connection pool: 98% used</dd></div><div><dt>Traces</dt><dd>Database connection wait increased</dd></div><div><dt>Deployment</dt><dd>v42 · before the alert</dd></div></dl>'),
        ('قطع worker','Worker interrupted','worker از دسترس می‌رود؛ اطلاعاتِ commit‌شدهٔ run هنوز در مخزن پایدار است.','The worker disappears; committed run state remains in durable storage.','Interrupted',
         '<div class="pov-incident">'+p('در نمایش، اجرای worker شمارهٔ ۷ قطع می‌شود. سرویس واقعی را kill نمی‌کنیم.','In the illustration, worker 7 is interrupted. No real service is killed.')+'</div><dl class="pov-config"><div><dt>Committed step</dt><dd>2 · retained</dd></div><div><dt>Run ID</dt><dd>run_demo_001 · unchanged</dd></div></dl>'),
        ('ادامهٔ همان run','Resume the same run','مالک تازه با epoch جدید ادامه می‌دهد؛ commit مالک قدیمی باید رد شود. هدف R01: دادهٔ تأییدشده گم نشود و بازیابی تا دو دقیقه.','A new epoch takes ownership; stale commits must be rejected. R01 targets no acknowledged-state loss and recovery within two minutes.','Resuming',
         '<dl class="pov-config"><div><dt>Owner epoch</dt><dd>7 → 8</dd></div><div><dt>Resume</dt><dd>After committed step 2</dd></div><div><dt>R01 objective</dt><dd>RPO = 0 · RTO ≤ 120 s · not measured</dd></div></dl>'),
        ('خواندن گزارش','Inspect the report','گزارش را همراهِ شاهد و عدم‌قطعیت می‌خوانم؛ ابزارِ دارای اثر در این نسخه اجرا نمی‌شود.','I inspect evidence and uncertainty. This version executes no side-effecting tool.','Report ready',
         '<div class="pov-report"><h4>'+twin('فرضیهٔ اول: اشباع connection pool','Leading hypothesis: connection-pool exhaustion')+'</h4>'+ul([('شاهد: استفادهٔ ۹۸٪ از pool و افزایش انتظار DB در trace.','Evidence: 98% pool usage and longer DB waits in traces.'),('ابهام: هم‌زمانی با deployment علت را ثابت نمی‌کند.','Uncertainty: deployment timing alone does not establish causation.'),('گام بعدِ پیشنهادی: بررسی leak و تنظیم pool توسط مهندس.','Suggested next step: an engineer checks for leaks and pool configuration.')])+'</div>'),
        ('آزمونِ نسخه','Evaluate the release','پیش از ارتقای نسخه، آزمونِ کیفیت و خرابی لازم است. این نمایش فقط مسیر کار را توضیح می‌دهد؛ eval واقعی اجرا نشده است.','Quality and failure tests precede promotion. This walkthrough illustrates the path; it runs no real evaluation.','Review required',
         '<div class="pov-report"><h4>'+twin('مدرکی که برای انتشار می‌خواهیم','Evidence required before release')+'</h4>'+ul([('نتیجهٔ holdout و مقایسه با baseline','Holdout results and a baseline comparison'),('drillهای RPO/RTO با زمان و دادهٔ مشاهده‌شده','RPO/RTO drills with observed times and data'),('کنترل ACL، حذف و worker قدیمی','ACL, deletion, and stale-worker checks')])+'<a class="workshop-link" href="#acceptance">'+twin('دیدن آزمون‌های برنامه‌ریزی‌شده','View planned acceptance tests')+icon('next')+'</a></div>'),
    ]
    navigation='<div class="pov-step-nav" hidden aria-label="Developer walkthrough">'
    articles=''
    options=''
    for i,(fa,en,nfa,nen,state,content) in enumerate(scenes):
        options+=f'<option value="{i}" data-fa="{i+1:02} · {fa}" data-en="{i+1:02} · {en}">{i+1:02} · {fa}</option>'
        navigation+=f'<button type="button" data-pov-select="{i}" aria-pressed="{str(i==0).lower()}"><bdi>{i+1:02}</bdi>'+twin(fa,en)+'</button>'
        articles+=f'<article data-pov-scene="{i}"><div class="pov-screen-heading"><h3>'+twin(fa,en)+f'</h3><span class="pov-state" dir="ltr">{state}</span></div>'+p(nfa,nen)+content+'</article>'
    navigation+='</div><label class="pov-mobile-nav" hidden>'+twin('انتخاب گام','Choose a step')+'<select id="pov-stage-select">'+options+'</select></label>'
    summary='<div class="outcome-summary"><div><h3>'+twin('آنچه الان ساخته‌ایم','What exists today')+'</h3>'+ul([('سایت آموزشی دو‌زبانه با ۱۴ فصل و یک کارگاه طراحی پلتفرم.','A bilingual 14-chapter study site and platform-design workshop.'),('۱۵ ADR، تخمین‌های قابل‌تغییر، قراردادهای بازیابی و نمودارهای معماری/UML.','15 ADRs, editable estimates, recovery contracts, and architecture/UML diagrams.'),('فلو و walkthrough نمایشی؛ محاسبات و کنترل‌های آن واقعاً در مرورگر کار می‌کنند.','Illustrative flow and walkthrough; their calculations and controls work locally in the browser.')])+'</div><div><h3>'+twin('پلتفرمی که این طرح توصیف می‌کند','The platform described by the design')+'</h3>'+p('توسعه‌دهنده app را تعریف می‌کند، run می‌فرستد و نتیجه و trace می‌گیرد؛ هستهٔ مشترک، context مجاز، اجرای پایدار، gateway و ارزیابی نسخه را فراهم می‌کند. API، worker، DB، CDC و serving این پلتفرم هنوز پیاده‌سازی نشده‌اند.','A developer defines an app, submits runs, and retrieves results/traces. Shared infrastructure provides authorized context, durable execution, a gateway, and release evaluation. Its APIs, workers, database, CDC, and model serving are not implemented yet.')+'</div></div>'
    player='<div class="pov-player" id="pov-player"><div class="pov-topline"><strong lang="en" dir="ltr">Own the Stack / Developer workspace</strong><span>'+twin('نمایش آموزشی با دادهٔ مصنوعی','Educational simulation · synthetic data')+'</span></div><div class="pov-layout">'+navigation+'<div class="pov-screen">'+articles+'</div></div><div class="pov-toolbar" hidden><button type="button" data-pov-play class="langbtn" aria-pressed="false">'+icon('play')+'<span data-pov-play-label>'+twin('پخش تجربه','Play walkthrough')+'</span></button><span data-pov-counter></span><div class="flow-manual"><button type="button" data-pov-prev class="quiet-button">'+icon('next')+twin('قبل','Previous')+'</button><button type="button" data-pov-next class="quiet-button">'+twin('بعد','Next')+icon('next')+'</button><button type="button" data-pov-reset class="quiet-button">'+icon('reset')+twin('از ابتدا','Restart')+'</button></div></div></div>'
    return '<section id="outcome" class="workshop-section outcome-section"><h2>'+twin('در پایان، چه چیزی داریم؟','What have we made?')+'</h2>'+summary+'<h3 class="pov-title">'+twin('از دید توسعه‌دهنده، یک بار مسیر را ببینیم','See the journey from the developer’s point of view')+'</h3>'+p('این POV یک پیش‌نمایش تعاملی از محصولِ پیشنهادی است؛ هیچ مدل، ابزار، DB یا سرویس خارجی را فراخوانی نمی‌کند. زمان پخش هم RTO اندازه‌گیری‌شده نیست.','This POV is an interactive preview of the proposed product. It calls no model, tool, database, or external service. Playback time is not a measured RTO.')+player+'<noscript>'+p('با JavaScript خاموش، همهٔ گام‌ها به‌صورت متن قابل‌خواندن‌اند.','With JavaScript disabled, all stages remain readable as text.')+'</noscript><div class="project-signature"><p>'+twin('طراحی، نگارش و نگهداری این پروژه:','Project design, writing, and maintenance:')+'</p><strong lang="en" dir="ltr">hurdad ashouri</strong><div class="workshop-links"><a href="https://github.com/Hurdadd/own-the-stack" class="workshop-link">GitHub'+icon('next')+'</a><a href="../README.md" class="workshop-link">README'+icon('next')+'</a><a href="../CONTRIBUTING.md" class="workshop-link">'+twin('مشارکت','Contributing')+icon('next')+'</a><a href="../LICENSE" class="workshop-link">AGPL-3.0-only'+icon('next')+'</a></div><p class="signature-note">'+twin('مجوز برای کار اصیل پروژه است؛ حقوق کتاب، فونت‌ها و اجزای ثالث طبق NOTICE و مجوز خودشان محفوظ است. وب‌سایت عمومی است؛ مخزن GitHub فعلاً خصوصی می‌ماند.','The license covers original project work; book, font, and third-party rights remain governed by NOTICE and their own licenses. The website is public; the GitHub repository remains private.')+'</p></div></section>'
